// Gerado pelo Sistema Zero Studio

SZGame2D.setupStage(800, 480, "#1a2240");
const nave = SZGame2D.createShip({ x: 400, y: 410, w: 54, h: 62, body: "#f87171", wings: "#60a5fa" });
const tiros = SZGame2D.createGroup();
const asteroides = SZGame2D.createGroup();
let pontos = 0;
SZGame2D.onKey("Space", function () {
  SZGame2D.spawnBullet(tiros, { x: SZGame2D.centerX(nave), y: SZGame2D.spriteY(nave), radius: 5, color: "#a3e635", vx: 0, vy: -9 });
  SZGame2D.playShoot();
});
SZGame2D.gameLoop(function update() {
  if (SZGame2D.sceneIs("jogando")) {
    SZGame2D.clear();
    SZGame2D.drawStarfield(ctx, 1);
    SZGame2D.arrowsX(nave, 7);
    SZGame2D.clampToScreen(nave, ctx);
    SZGame2D.drawSprite(ctx, nave);
    SZGame2D.updateGroup(tiros);
    SZGame2D.pruneOffscreen(ctx, tiros, 40, function (sprite) {

    });
    SZGame2D.drawGroup(ctx, tiros);
    if (SZGame2D.everyFrames("cada", 40)) {
      SZGame2D.spawnAsteroid(asteroides, { x: SZGame2D.randomX(), y: -30, size: 40, color: "#aab1cf", vx: 0, vy: 3 });
    }
    SZGame2D.updateGroup(asteroides);
    SZGame2D.drawGroup(ctx, asteroides);
    SZGame2D.pruneOffscreen(ctx, asteroides, 40, function (sprite) {

    });
    SZGame2D.overlapGroups(tiros, asteroides, function (tiro, asteroide) {
      SZGame2D.removeFromGroup(tiros, tiro);
      SZGame2D.removeFromGroup(asteroides, asteroide);
      pontos = pontos + 1;
      SZGame2D.explodeSprite(asteroide, "#fb923c");
      SZGame2D.playExplosion();
    });
    SZGame2D.drawScore(ctx, "Pontos:", pontos, 12, 30, "#ffffff", 24);
    SZGame2D.overlapSpriteGroup(() => nave, asteroides, function (inimigo) {
      SZGame2D.shake(ctx, 8);
      SZGame2D.blink(nave, 60);
      vidas = vidas + -1;
    });
    SZGame2D.drawHearts(ctx, vidas, 10, 10, 22, "#ffffff");
    if (pontos >= alvo) {
      SZGame2D.setScene("ganhou");
    }
    if (vidas <= 0) {
      SZGame2D.setScene("perdeu");
    }
  }
  if (SZGame2D.sceneIs("inicio")) {
    SZGame2D.showScreen(ctx, "Nave contra Asteroides", "", "", "#ffffff");
  }
});
let vidas = 3;
const alvo = 26;
SZGame2D.setScene("inicio");
SZGame2D.onKey("Enter", function () {
  if (SZGame2D.sceneIs("inicio")) {
    SZGame2D.setScene("jogando");
  }
});
